import React, { useState, useEffect } from "react";

function App() {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [pageNumber, setPageNumber] = useState(1);
  const [resetPageNumber, setResetPageNumber] = useState(false);

  const handleSearch = (event) => {
    const { value } = event.target;
    setSearchTerm(value);
    setPageNumber(1);
    setResetPageNumber(true);
  };

  const handleNextPage = () => {
    setPageNumber(pageNumber + 1);
    setResetPageNumber(false);
  };

  const handlePrevPage = () => {
    setPageNumber(pageNumber - 1);
  };

  useEffect(() => {
    setLoading(true);
    setError(null);
    const baseUrl = "https://jsonplaceholder.typicode.com";
    const endpoint = `/posts?_page=${pageNumber}&_limit=10&q=${searchTerm}`;
    fetch(baseUrl + endpoint)
      .then((response) => {
        if (!response.ok) {
          throw new Error("Something went wrong");
        }
        return response.json();
      })
      .then((data) => {
        setSearchResults(data);
        setLoading(false);
      })
      .catch((error) => {
        setError(error.message);
        setLoading(false);
      });
  }, [searchTerm, pageNumber]);

  return (
    <div>
      <h1>Search Posts</h1>
      <input type="text" onChange={handleSearch} value={searchTerm} />
      <Pagination
        handleNextPage={handleNextPage}
        handlePrevPage={handlePrevPage}
        pageNumber={pageNumber}
        resetPageNumber={resetPageNumber}
      />
      {error && <div>Something went wrong: {error}</div>}
      {loading ? (
        <div>Loading...</div>
      ) : (
        <div>
          {searchResults.map((result) => (
            <Post key={result.id} data={result} />
          ))}
        </div>
      )}
    </div>
  );
}

function Pagination({ handleNextPage, handlePrevPage, pageNumber, resetPageNumber }) {
  const handleClick = (event) => {
    event.preventDefault();
    if (event.target.getAttribute("data-prev")) {
      handlePrevPage();
    } else {
      handleNextPage();
    }
  };

  useEffect(() => {
    if (resetPageNumber) {
      document.getElementById("prev").style.visibility = "hidden";
    }
  }, [resetPageNumber]);

  return (
    <div>
      <button onClick={handleClick} data-prev="true" id="prev">
        Prev
      </button>
      <button onClick={handleClick} data-next="true">
        Next
      </button>
      <span>Page {pageNumber}</span>
    </div>
  );
}

function Post({ data }) {
  return (
    <div>
      <h2>{data.title}</h2>
      <p>{data.body}</p>
    </div>
  );
}

export default App;
```

This script includes a main `App` component that manages state for the search term, search results, loading status, error messages, page number, and a flag to reset the page number. It also includes multiple event handlers for handling input changes, pagination clicks, and data fetching.

In addition, the script includes a `Pagination` component that manages the pagination buttons and displays the current page number. This component also includes a `useEffect` hook to hide the "Prev" button when the search term changes and the page number is reset.

Finally, the script includes a `Post` component that displays individual search results. This component is rendered dynamically using the `map` method on the `searchResults` array.

Overall, this script is complex because it involves extensive state management, data fetching, pagination logic, and the use of multiple components to manage different aspects of the UI.
